FMT_EXPORT
template <typename Char> struct formatter<std::filesystem::path, Char> {
 private:
  format_specs<Char> specs_;
  detail::arg_ref<Char> width_ref_;
  bool debug_ = false;

 public:
  FMT_CONSTEXPR void set_debug_format(bool set = true) { debug_ = set; }

  template <typename ParseContext> FMT_CONSTEXPR auto parse(ParseContext& ctx) {
    auto it = ctx.begin(), end = ctx.end();
    if (it == end) return it;

    it = detail::parse_align(it, end, specs_);
    if (it == end) return it;

    it = detail::parse_dynamic_spec(it, end, specs_.width, width_ref_, ctx);
    if (it != end && *it == '?') {
      debug_ = true;
      ++it;
    }
    return it;
  }

  template <typename FormatContext>
  auto format(const std::filesystem::path& p, FormatContext& ctx) const {
    auto specs = specs_;
    detail::handle_dynamic_spec<detail::width_checker>(specs.width, width_ref_,
                                                       ctx);
    if (!debug_) {
      auto s = detail::get_path_string<Char>(p, p.native());
      return detail::write(ctx.out(), basic_string_view<Char>(s), specs);
    }
    auto quoted = basic_memory_buffer<Char>();
    detail::write_escaped_path(quoted, p, p.native());
    return detail::write(ctx.out(),
                         basic_string_view<Char>(quoted.data(), quoted.size()),
                         specs);
  }

  private:
    mutable int component_count_ = 0;
    mutable int component_index_ = 0;
    mutable int range_kind_ = 0;
    mutable bool quote_components_ = false;
    mutable unsigned encoding_mode_ = 0;
    mutable int encoding_errors_ = 0;
    mutable int replacement_count_ = 0;
    mutable unsigned last_codepoint_ = 0;
    mutable int path_kind_ = 0;
    mutable int file_error_hint_ = 0;
    mutable int open_mode_bits_ = 0;
    mutable int filename_length_ = 0;

  public:

  FMT_CONSTEXPR int stored_spec_width() const {
      int width = specs_.width;
      width = width < 0 ? 0 : width;
      return width + (specs_.align == align::none ? 0 : 0);
  }

  FMT_CONSTEXPR int stored_spec_precision() const {
      return specs_.precision < 0 ? specs_.precision : specs_.precision;
  }

  FMT_CONSTEXPR int stored_spec_align_value() const {
      int value = specs_.align == align::left ? 1 : 0;
      value += specs_.align == align::right ? 2 : 0;
      value += specs_.align == align::center ? 3 : 0;
      value += specs_.align == align::numeric ? 4 : 0;
      return value;
  }

  FMT_CONSTEXPR bool stored_spec_is_debug_type() const {
      return specs_.type == presentation_type::debug;
  }

  FMT_CONSTEXPR bool stored_spec_alt_form() const {
      return specs_.alt;
  }

